const toIng = ([name, qty, unit, cat]) => ({ name, qty, unit, cat });
export const RECIPES = [
  ...BASE,
  ...MORE.map(({ ing, ...r }) => ({ ...r, ingredients: ing.map(toIng) })),
];

export const SEASONS = { all: "ganzjährig", q1: "Winter", q2: "Frühling", q3: "Sommer", q4: "Herbst" };
export const quarterOf = (date) => "q" + (Math.floor(date.getMonth() / 3) + 1);
// Gerichte, die für das Quartal des Datums angeboten werden
export const activeRecipes = (date) => {
  const q = quarterOf(date);
  return RECIPES.filter((r) => !r.retired && (r.season === "all" || r.season === q));
};

